// FRONTEND_BASE_URL must be set as an n8n environment variable (the origin
// the React app is served from) — same idea as the ngrok backend URL, just
// for the other direction (links n8n emails point back INTO the app).
const row = $input.item.json;
// $env access can be blocked entirely by the n8n instance's own security settings (N8N_BLOCK_ENV_ACCESS_IN_NODE) — reading a blocked var THROWS rather than returning undefined, so the `|| ''` fallback never gets a chance to run without this try/catch.
let base = '';
try { base = $env.FRONTEND_BASE_URL || ''; } catch (e) { base = ''; }
const link = `${base}/documents/proposal/${row.public_token}`;

function fill(template) {
  return (template || '')
    .replace(/{{\s*first_name\s*}}/gi, row.first_name || 'there')
    .replace(/{{\s*last_name\s*}}/gi, row.last_name || '')
    .replace(/{{\s*deal_name\s*}}/gi, row.deal_name || '')
    .replace(/{{\s*owner_name\s*}}/gi, row.owner_name || 'your account team')
    .replace(/{{\s*owner_email\s*}}/gi, row.owner_email || '')
    .replace(/{{\s*owner_phone\s*}}/gi, row.owner_phone || '')
    .replace(/{{\s*proposal_link\s*}}/gi, link);
}

return [{
  json: {
    proposalId: row.proposal_id,
    to: row.email,
    subject: fill(row.email_subject),
    body: fill(row.email_body),
  },
}];

